## 5. Provider Router 구현

### `src/router/PaymentProviderRouter.ts`

```ts
import { PaymentProvider } from '../providers/PaymentProvider';
import { CreatePaymentRequest } from '../types/payment';

export class PaymentProviderRouter {
  constructor(
    private readonly providers: PaymentProvider[],
  ) {
    if (providers.length === 0) {
      throw new Error('At least one payment provider must be registered.');
    }
  }

  getProvider(request: CreatePaymentRequest): PaymentProvider {
    // 1. 명시적 provider 지정 시 우선 선택
    if (request.provider) {
      const matched = this.providers.find((provider) => provider.type === request.provider);
      if (!matched) {
        throw new Error(`Provider not found: ${request.provider}`);
      }
      return matched;
    }

    // 2. supports() 기반 자동 선택
    const supportedProviders = this.providers.filter((provider) => provider.supports(request));

    if (supportedProviders.length === 0) {
      throw new Error(
        `No provider supports this request. currency=${request.currency}, amount=${request.amount}`,
      );
    }

    if (supportedProviders.length > 1) {
      // 실무에서는 우선순위 정책을 두는 것이 좋음
      return supportedProviders[0];
    }

    return supportedProviders[0];
  }
}
```

---

## 6. 서비스 레이어

### `src/services/PaymentService.ts`

```ts
import { PaymentProviderRouter } from '../router/PaymentProviderRouter';
import { CreatePaymentRequest, PaymentResult } from '../types/payment';

export class PaymentService {
  constructor(
    private readonly providerRouter: PaymentProviderRouter,
  ) {}

  async createPayment(request: CreatePaymentRequest): Promise<PaymentResult> {
    if (request.amount <= 0) {
      throw new Error('Amount must be greater than 0.');
    }

    const provider = this.providerRouter.getProvider(request);
    return provider.createPayment(request);
  }
}
```

---

## 7. 실행 예시

### `src/index.ts`

```ts
import { StripeProvider } from './providers/StripeProvider';
import { TossProvider } from './providers/TossProvider';
import { PaymentProviderRouter } from './router/PaymentProviderRouter';
import { PaymentService } from './services/PaymentService';

async function main(): Promise<void> {
  const stripeProvider = new StripeProvider();
  const tossProvider = new TossProvider();

  const router = new PaymentProviderRouter([
    stripeProvider,
    tossProvider,
  ]);

  const paymentService = new PaymentService(router);

  const result1 = await paymentService.createPayment({
    userId: 'user-1',
    amount: 10000,
    currency: 'KRW',
  });

  console.log('KRW payment result:', result1);

  const result2 = await paymentService.createPayment({
    userId: 'user-2',
    amount: 50,
    currency: 'USD',
  });

  console.log('USD payment result:', result2);

  const result3 = await paymentService.createPayment({
    userId: 'user-3',
    amount: 25,
    currency: 'USD',
    provider: 'stripe',
  });

  console.log('Explicit provider result:', result3);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
```

