import { PaymentProvider } from '../providers/PaymentProvider';
import { CreatePaymentRequest } from '../types/payment';

export class PaymentProviderRouter {
  private readonly providers: PaymentProvider[];

  constructor(providers: PaymentProvider[]) {
    if (providers.length === 0) {
      throw new Error('At least one payment provider must be registered.');
    }

    this.providers = [...providers].sort((a, b) => b.priority - a.priority);
  }

  getProvider(request: CreatePaymentRequest): PaymentProvider {
    if (request.provider) {
      const matched = this.providers.find((provider) => provider.type === request.provider);
      if (!matched) {
        throw new Error(`Provider not found: ${request.provider}`);
      }
      return matched;
    }

    const matched = this.providers.find((provider) => provider.supports(request));
    if (!matched) {
      throw new Error(
        `No provider supports this request. currency=${request.currency}, amount=${request.amount}`,
      );
    }

    return matched;
  }
}
