## 3) Orchestrator 구현

```ts
export class AIOrchestrator {
  private readonly providers: AIProvider[];
  private readonly timeoutMsPerProvider: number;
  private readonly maxRetriesPerProvider: number;
  private readonly retryDelayMs: number;
  private readonly logger: Logger;
  private readonly shouldRetry: (error: unknown) => boolean;

  constructor(providers: AIProvider[], options: OrchestratorOptions = {}) {
    if (!providers.length) {
      throw new Error("At least one provider is required");
    }

    this.providers = providers;
    this.timeoutMsPerProvider = options.timeoutMsPerProvider ?? 15_000;
    this.maxRetriesPerProvider = options.maxRetriesPerProvider ?? 1;
    this.retryDelayMs = options.retryDelayMs ?? 500;
    this.shouldRetry = options.shouldRetry ?? defaultShouldRetry;
    this.logger = options.logger ?? consoleLogger;
  }

  async generate(request: AIRequest): Promise<OrchestratorResult> {
    const attempts: FallbackAttempt[] = [];
    const errors: ProviderError[] = [];

    for (const provider of this.providers) {
      const startedAt = new Date().toISOString();

      try {
        const response = await this.tryProviderWithRetry(provider, request);

        const endedAt = new Date().toISOString();
        attempts.push({
          provider: provider.name,
          model: provider.model,
          startedAt,
          endedAt,
          success: true,
        });

        this.logger.info("AI provider succeeded", {
          provider: provider.name,
          model: provider.model,
        });

        return {
          response,
          attempts,
        };
      } catch (error) {
        const normalized = normalizeError(provider.name, error);
        errors.push(normalized);

        const endedAt = new Date().toISOString();
        attempts.push({
          provider: provider.name,
          model: provider.model,
          startedAt,
          endedAt,
          success: false,
          error: {
            name: normalized.name,
            message: normalized.message,
            code: normalized.code,
            retryable: normalized.retryable,
            status: normalized.status,
          },
        });

        this.logger.warn("AI provider failed, trying fallback", {
          provider: provider.name,
          model: provider.model,
          code: normalized.code,
          message: normalized.message,
          retryable: normalized.retryable,
          status: normalized.status,
        });
      }
    }

    const summary = errors.map((e) => ({
      provider: e.provider,
      code: e.code,
      message: e.message,
      retryable: e.retryable,
      status: e.status,
    }));

    this.logger.error("All AI providers failed", { errors: summary });

    throw new Error(
      `All AI providers failed: ${summary
        .map((e) => `${e.provider}[${e.code}] ${e.message}`)
        .join(" | ")}`
    );
  }

  private async tryProviderWithRetry(
    provider: AIProvider,
    request: AIRequest,
  ): Promise<AIResponse> {
    let lastError: unknown;

    for (let attempt = 0; attempt <= this.maxRetriesPerProvider; attempt++) {
      try {
        this.logger.info("Calling AI provider", {
          provider: provider.name,
          model: provider.model,
          attempt: attempt + 1,
        });

        const response = await withTimeout(
          (signal) => provider.generate({ ...request, signal }),
          this.timeoutMsPerProvider,
          request.signal,
        );

        return response;
      } catch (error) {
        lastError = normalizeError(provider.name, error);

        const retry = attempt < this.maxRetriesPerProvider && this.shouldRetry(lastError);

        this.logger.warn("AI provider attempt failed", {
          provider: provider.name,
          model: provider.model,
          attempt: attempt + 1,
          retry,
          error:
            lastError instanceof ProviderError
              ? {
                  code: lastError.code,
                  message: lastError.message,
                  retryable: lastError.retryable,
                  status: lastError.status,
                }
              : String(lastError),
        });

        if (!retry) {
          throw lastError;
        }

        await sleep(this.retryDelayMs * (attempt + 1));
      }
    }

    throw lastError;
  }
}

const consoleLogger: Logger = {
  info(message, meta) {
    console.info(message, meta ?? {});
  },
  warn(message, meta) {
    console.warn(message, meta ?? {});
  },
  error(message, meta) {
    console.error(message, meta ?? {});
  },
};
```

