  winner: "A" | "B" | "tie";
  confidence: number; // 0-1
  scores: {
    A: DimensionScore;
    B: DimensionScore;
  };
  rationale: string;
  issues?: string[];
}

export interface JudgeResult {
  winner: CandidateModel | "tie";
  confidence: number;
  normalizedScores: {
    openai: number;
    claude: number;
  };
  passResults: {
    forward: JudgePassResult;
    reverse: JudgePassResult;
  };
  rationale: string;
  method: "rule_based" | "llm_judge" | "hybrid";
}
