# Rule-based 사전 검사 구현

이 단계는 간단하지만 매우 유용합니다.

```ts
export interface PrecheckResult {
  openaiPenalty: number;
  claudePenalty: number;
  openaiIssues: string[];
  claudeIssues: string[];
}

function basicPrecheck(input: JudgeInput): PrecheckResult {
  const result: PrecheckResult = {
    openaiPenalty: 0,
    claudePenalty: 0,
    openaiIssues: [],
    claudeIssues: [],
  };

  const check = (label: "openai" | "claude", text: string) => {
    let penalty = 0;
    const issues: string[] = [];

    if (!text || text.trim().length === 0) {
      penalty += 100;
      issues.push("empty_response");
    }

    if (text.trim().length > 0 && text.trim().length < 20) {
      penalty += 15;
      issues.push("too_short");
    }

    // JSON 요청인데 JSON이 아니면 패널티
    if (input.taskType === "json") {
      try {
        JSON.parse(text);
      } catch {
        penalty += 25;
        issues.push("invalid_json");
      }
    }

    // 코드 요청인데 코드 블록/코드 흔적이 너무 없으면 패널티
    if (input.taskType === "code") {
      const hasCodeLikePattern =
        /```|function |const |let |class |interface |type |import |export /.test(text);
      if (!hasCodeLikePattern) {
        penalty += 20;
        issues.push("missing_code");
      }
    }

    return { penalty, issues };
  };

  const openai = check("openai", input.openaiResponse);
  const claude = check("claude", input.claudeResponse);

  result.openaiPenalty = openai.penalty;
  result.claudePenalty = claude.penalty;
  result.openaiIssues = openai.issues;
  result.claudeIssues = claude.issues;

  return result;
}
```

