export type ProviderName = "openai" | "anthropic" | "google" | "custom";

export interface ProviderResponse<T = unknown> {
  provider: ProviderName;
  success: boolean;
  data?: T;
  error?: string;

  // metrics for scoring
  latencyMs: number;       // lower is better
  confidence?: number;     // 0 ~ 1, higher is better
  completeness?: number;   // 0 ~ 1, higher is better
  freshness?: number;      // 0 ~ 1, higher is better
  costUsd?: number;        // lower is better
}

export interface ScoreWeights {
  success: number;
  latency: number;
  confidence: number;
  completeness: number;
  freshness: number;
  cost: number;
}

export interface ScoreBreakdown {
  success: number;
  latency: number;
  confidence: number;
  completeness: number;
  freshness: number;
  cost: number;
  total: number;
}

export interface ScoredProvider<T = unknown> {
  response: ProviderResponse<T>;
  score: ScoreBreakdown;
}

export interface WinnerResult<T = unknown> {
  winner: ScoredProvider<T> | null;
  ranked: ScoredProvider<T>[];
}

