  weights?: Partial<ScoreWeights>;

  // normalization bounds
  maxLatencyMs?: number;
  maxCostUsd?: number;

  // minimum quality gate
  minConfidence?: number;
  minCompleteness?: number;

  // if true, failed responses are still ranked with low score
  includeFailedProviders?: boolean;
}

