  if (value == null || Number.isNaN(value)) return 0;
  return clamp(value, 0, 1);
}

function normalizeLowerBetter(value: number | undefined, maxValue: number): number {
  if (value == null || Number.isNaN(value)) return 0;
  if (maxValue <= 0) return 0;
  return clamp(1 - value / maxValue, 0, 1);
}

