    ...options,
    weights: {
      ...DEFAULT_WEIGHTS,
      ...(options?.weights ?? {}),
    },
  };

  const scored = responses
    .map((r) => scoreProvider(r, mergedOptions))
    .filter((item) => {
      if (mergedOptions.includeFailedProviders) return true;
      return item.response.success;
    });

  scored.sort((a, b) => {
    // 1. total score desc
    if (b.score.total !== a.score.total) {
