    const aConfidence = a.response.confidence ?? 0;
    const bConfidence = b.response.confidence ?? 0;
    if (bConfidence !== aConfidence) {
      return bConfidence - aConfidence;
    }

    // 4. lower latency
    if (a.response.latencyMs !== b.response.latencyMs) {
      return a.response.latencyMs - b.response.latencyMs;
    }

    // 5. lower cost
    const aCost = a.response.costUsd ?? Number.MAX_SAFE_INTEGER;
    const bCost = b.response.costUsd ?? Number.MAX_SAFE_INTEGER;
    if (aCost !== bCost) {
      return aCost - bCost;
    }

