export interface ProviderResponse<T = unknown> {
  provider: ProviderName;
  success: boolean;
  data?: T;
  error?: string;

  // metrics for scoring
  latencyMs: number;       // lower is better
  confidence?: number;     // 0 ~ 1, higher is better
  completeness?: number;   // 0 ~ 1, higher is better
  freshness?: number;      // 0 ~ 1, higher is better
  costUsd?: number;        // lower is better
}

export interface ScoreWeights {
  success: number;
  latency: number;
  confidence: number;
  completeness: number;
  freshness: number;
  cost: number;
}

export interface ScoreBreakdown {
  success: number;
  latency: number;
  confidence: number;
  completeness: number;
  freshness: number;
  cost: number;
  total: number;
}

export interface ScoredProvider<T = unknown> {
  response: ProviderResponse<T>;
  score: ScoreBreakdown;
}

export interface WinnerResult<T = unknown> {
  winner: ScoredProvider<T> | null;
  ranked: ScoredProvider<T>[];
}

export interface ScoreboardOptions {
  weights?: Partial<ScoreWeights>;

  // normalization bounds
  maxLatencyMs?: number;
  maxCostUsd?: number;

  // minimum quality gate
  minConfidence?: number;
  minCompleteness?: number;

  // if true, failed responses are still ranked with low score
  includeFailedProviders?: boolean;
}

const DEFAULT_WEIGHTS: ScoreWeights = {
  success: 40,
  latency: 15,
  confidence: 20,
  completeness: 15,
  freshness: 5,
  cost: 5,
};

const DEFAULT_OPTIONS: Required<ScoreboardOptions> = {
  weights: DEFAULT_WEIGHTS,
  maxLatencyMs: 10_000,
  maxCostUsd: 0.05,
  minConfidence: 0,
  minCompleteness: 0,
  includeFailedProviders: true,
};

function clamp(value: number, min = 0, max = 1): number {
  return Math.max(min, Math.min(max, value));
}

function normalizeHigherBetter(value: number | undefined): number {
  if (value == null || Number.isNaN(value)) return 0;
  return clamp(value, 0, 1);
}

function normalizeLowerBetter(value: number | undefined, maxValue: number): number {
  if (value == null || Number.isNaN(value)) return 0;
  if (maxValue <= 0) return 0;
  return clamp(1 - value / maxValue, 0, 1);
}

export function scoreProvider<T>(
  response: ProviderResponse<T>,
  options?: ScoreboardOptions
): ScoredProvider<T> {
  const mergedOptions: Required<ScoreboardOptions> = {
    ...DEFAULT_OPTIONS,
    ...options,
    weights: {
      ...DEFAULT_WEIGHTS,
      ...(options?.weights ?? {}),
    },
  };

  const { weights, maxLatencyMs, maxCostUsd, minConfidence, minCompleteness } = mergedOptions;

  const confidence = normalizeHigherBetter(response.confidence);
  const completeness = normalizeHigherBetter(response.completeness);
  const freshness = normalizeHigherBetter(response.freshness);
  const latency = normalizeLowerBetter(response.latencyMs, maxLatencyMs);
  const cost = normalizeLowerBetter(response.costUsd ?? maxCostUsd, maxCostUsd);

  const passesQualityGate =
    confidence >= minConfidence && completeness >= minCompleteness;

  const successScore =
    response.success && passesQualityGate ? weights.success : 0;

  const breakdown: ScoreBreakdown = {
    success: successScore,
    latency: latency * weights.latency,
    confidence: confidence * weights.confidence,
    completeness: completeness * weights.completeness,
    freshness: freshness * weights.freshness,
    cost: cost * weights.cost,
    total: 0,
  };

  breakdown.total =
    breakdown.success +
    breakdown.latency +
    breakdown.confidence +
    breakdown.completeness +
    breakdown.freshness +
    breakdown.cost;

  return {
    response,
    score: breakdown,
  };
}

export function rankProviders<T>(
  responses: ProviderResponse<T>[],
  options?: ScoreboardOptions
): ScoredProvider<T>[] {
  const mergedOptions: Required<ScoreboardOptions> = {
    ...DEFAULT_OPTIONS,
    ...options,
    weights: {
      ...DEFAULT_WEIGHTS,
      ...(options?.weights ?? {}),
    },
  };

  const scored = responses
    .map((r) => scoreProvider(r, mergedOptions))
    .filter((item) => {
      if (mergedOptions.includeFailedProviders) return true;
      return item.response.success;
    });

  scored.sort((a, b) => {
    // 1. total score desc
    if (b.score.total !== a.score.total) {
      return b.score.total - a.score.total;
    }

    // 2. success first
    if (a.response.success !== b.response.success) {
      return a.response.success ? -1 : 1;
    }

    // 3. higher confidence
    const aConfidence = a.response.confidence ?? 0;
    const bConfidence = b.response.confidence ?? 0;
    if (bConfidence !== aConfidence) {
      return bConfidence - aConfidence;
    }

    // 4. lower latency
    if (a.response.latencyMs !== b.response.latencyMs) {
      return a.response.latencyMs - b.response.latencyMs;
    }

    // 5. lower cost
    const aCost = a.response.costUsd ?? Number.MAX_SAFE_INTEGER;
    const bCost = b.response.costUsd ?? Number.MAX_SAFE_INTEGER;
    if (aCost !== bCost) {
      return aCost - bCost;
    }

    // 6. stable provider name ordering
    return a.response.provider.localeCompare(b.response.provider);
  });

  return scored;
}

export function pickWinner<T>(
  responses: ProviderResponse<T>[],
  options?: ScoreboardOptions
): WinnerResult<T> {
  const ranked = rankProviders(responses, options);
  const winner = ranked.length > 0 ? ranked[0] : null;
  return { winner, ranked };
}
