```ts
import {
  ExecutionResult,
  ExecutionStepResult,
  Executor,
  Plan,
  PlanStep,
} from "./types";

function nowIso(): string {
  return new Date().toISOString();
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export class SimpleExecutor implements Executor {
  constructor(private readonly maxRetries: number = 1) {}

  async execute(plan: Plan): Promise<ExecutionResult> {
    const stepResults: ExecutionStepResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeWithRetry(step, this.maxRetries);
      stepResults.push(result);

      if (!result.success) {
        return {
          success: false,
          stepResults,
          summary: `Execution failed at step ${step.id}: ${result.error}`,
        };
      }
    }

    return {
      success: true,
      stepResults,
      summary: "All steps executed successfully",
    };
  }

  private async executeWithRetry(
    step: PlanStep,
    maxRetries: number
  ): Promise<ExecutionStepResult> {
    let attempt = 0;
    let lastError: unknown;

    while (attempt <= maxRetries) {
      try {
        return await this.executeStep(step);
      } catch (error) {
        lastError = error;
        attempt += 1;

        if (attempt <= maxRetries) {
          await sleep(200 * attempt);
        }
      }
    }

    const startedAt = nowIso();
    const finishedAt = nowIso();

    return {
      stepId: step.id,
      success: false,
      error: lastError instanceof Error ? lastError.message : "Unknown error",
      startedAt,
      finishedAt,
      durationMs: 0,
    };
  }

  private async executeStep(step: PlanStep): Promise<ExecutionStepResult> {
    const started = Date.now();
    const startedAt = new Date(started).toISOString();

    let output: unknown;

    switch (step.action) {
      case "validate-input": {
        const goal = step.payload?.goal;
        if (typeof goal !== "string" || goal.trim().length === 0) {
          throw new Error("Invalid goal");
        }
        output = { valid: true };
        break;
      }

      case "perform-main-task": {
        const goal = step.payload?.goal;
        await sleep(300);

        if (typeof goal !== "string") {
          throw new Error("Goal is missing");
        }

        output = {
          message: `Main task completed for goal: ${goal}`,
          processed: true,
        };
        break;
      }

      case "summarize-result": {
        await sleep(100);
        output = {
          summary: "Result summarized successfully",
        };
        break;
      }

      default:
        throw new Error(`Unsupported action: ${step.action}`);
    }

    const finished = Date.now();
    const finishedAt = new Date(finished).toISOString();

    return {
      stepId: step.id,
      success: true,
      output,
      startedAt,
      finishedAt,
      durationMs: finished - started,
    };
  }
}
```

