## `src/judge.ts`

judge는 실행 결과를 보고 승인/반려를 결정합니다.

```ts
import { Judge, JudgeResult } from "./types";

export class SimpleJudge implements Judge {
  async evaluate(input: {
    workflowInput: { goal: string };
    plan: { steps: { id: string }[] };
    executionResult: { success: boolean; stepResults: { success: boolean }[] };
  }): Promise<JudgeResult> {
    const { executionResult, plan } = input;

    const successfulSteps = executionResult.stepResults.filter(
      (s) => s.success
    ).length;

    const totalSteps = plan.steps.length;
    const score =
      totalSteps === 0 ? 0 : Math.round((successfulSteps / totalSteps) * 100);

    const reasons: string[] = [];

    if (!executionResult.success) {
      reasons.push("Execution result indicates failure");
    }

    if (successfulSteps !== totalSteps) {
      reasons.push(
        `Only ${successfulSteps} of ${totalSteps} steps completed successfully`
      );
    }

    if (reasons.length === 0) {
      reasons.push("All planned steps completed successfully");
    }

    return {
      approved: executionResult.success && successfulSteps === totalSteps,
      score,
      reasons,
    };
  }
}
```

