## `src/orchestrator.ts`

오케스트레이터가 전체 상태를 관리합니다.

```ts
import { Logger } from "./logger";
import {
  Executor,
  Judge,
  Planner,
  WorkflowInput,
  WorkflowState,
} from "./types";
import { randomUUID } from "crypto";

export class WorkflowOrchestrator {
  constructor(
    private readonly planner: Planner,
    private readonly executor: Executor,
    private readonly judge: Judge,
    private readonly logger: Logger
  ) {}

  async run(input: WorkflowInput): Promise<WorkflowState> {
    const workflowId = randomUUID();
    const createdAt = new Date().toISOString();

    const state: WorkflowState = {
      workflowId,
      status: "PENDING",
      input,
      createdAt,
      updatedAt: createdAt,
    };

    try {
      this.logger.info("Workflow started", {
        workflowId,
        goal: input.goal,
      });

      state.status = "PLANNED";
      state.updatedAt = new Date().toISOString();
      state.plan = await this.planner.createPlan(input);

      this.logger.info("Plan created", {
        workflowId,
        stepCount: state.plan.steps.length,
      });

      state.status = "EXECUTING";
      state.updatedAt = new Date().toISOString();
      state.executionResult = await this.executor.execute(state.plan);

      this.logger.info("Execution completed", {
        workflowId,
        success: state.executionResult.success,
      });

      state.status = "JUDGING";
      state.updatedAt = new Date().toISOString();
      state.judgeResult = await this.judge.evaluate({
        workflowInput: state.input,
        plan: state.plan,
        executionResult: state.executionResult,
      });

      this.logger.info("Judging completed", {
        workflowId,
        approved: state.judgeResult.approved,
        score: state.judgeResult.score,
      });

      state.status = state.judgeResult.approved ? "SUCCEEDED" : "FAILED";
      state.updatedAt = new Date().toISOString();

      return state;
    } catch (error) {
      state.status = "FAILED";
      state.updatedAt = new Date().toISOString();
      state.error = error instanceof Error ? error.message : "Unknown error";

      this.logger.error("Workflow failed", {
        workflowId,
        error: state.error,
      });

      return state;
    }

