# 5) Provider Router

명시적으로 `provider`가 들어오면 `Map`으로 바로 찾고,  
없으면 `supports()`를 기준으로 자동 선택하게 만들겠습니다.

## `src/providers/provider-router.ts`

```ts
import { Provider } from './provider.interface';
import { ChatRequest, ChatResponse } from '../types';

export class ProviderNotFoundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ProviderNotFoundError';
  }
}

export class ProviderRouter {
  private readonly providerMap: Map<string, Provider>;

  constructor(private readonly providers: Provider[]) {
    if (providers.length === 0) {
      throw new Error('ProviderRouter requires at least one provider');
    }

    this.providerMap = new Map();

    for (const provider of providers) {
      if (this.providerMap.has(provider.name)) {
        throw new Error(`Duplicate provider name detected: ${provider.name}`);
      }
      this.providerMap.set(provider.name, provider);
    }
  }

  resolve(request: ChatRequest): Provider {
    // 1. provider가 명시된 경우
    if (request.provider) {
      const provider = this.providerMap.get(request.provider);

      if (!provider) {
        throw new ProviderNotFoundError(
          `Provider "${request.provider}" is not registered`,
        );
      }

      return provider;
    }

    // 2. provider가 없으면 supports()로 자동 선택
    const provider = this.providers.find((p) => p.supports(request));

    if (!provider) {
      throw new ProviderNotFoundError(
        `No provider supports model "${request.model}"`,
      );
    }

    return provider;
  }

  async chat(request: ChatRequest): Promise<ChatResponse> {
    const provider = this.resolve(request);
    return provider.chat(request);
  }
}
```

