아래는 **여러 AI provider를 순차 호출하고, 실패 시 fallback** 하는 **production-usable TypeScript 예시**입니다.

특징:
- provider별 timeout
- 재시도 가능 구조
- 에러 표준화
- abort signal 지원
- 로깅 포인트 포함
- 유지보수 가능한 인터페이스 분리

---

## 1) 타입 정의

```ts
// ai-orchestrator.ts

export type AIProviderName = "openai" | "anthropic" | "google";

export interface AIMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface AIRequest {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
}

export interface AIUsage {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
}

export interface AIResponse {
  provider: AIProviderName;
  model: string;
  content: string;
  usage?: AIUsage;
  raw?: unknown;
}

export type AIErrorCode =
  | "TIMEOUT"
  | "ABORTED"
  | "RATE_LIMIT"
  | "AUTH"
  | "INVALID_REQUEST"
  | "UPSTREAM"
  | "UNKNOWN";

export class AIProviderError extends Error {
  public readonly provider: AIProviderName;
  public readonly code: AIErrorCode;
  public readonly status?: number;
  public readonly retryable: boolean;
  public readonly cause?: unknown;

  constructor(params: {
    provider: AIProviderName;
    code: AIErrorCode;
    message: string;
    status?: number;
    retryable?: boolean;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "AIProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.status = params.status;
    this.retryable = params.retryable ?? false;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  name: AIProviderName;
  model: string;
  generate(request: AIRequest): Promise<AIResponse>;
}
```

---

## 2) 공통 유틸리티

```ts
function isAbortError(err: unknown): boolean {
  return err instanceof Error && err.name === "AbortError";
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms);

    if (signal) {
      const onAbort = () => {
        clearTimeout(timer);
        reject(new DOMException("Aborted", "AbortError"));
      };

      if (signal.aborted) {
        clearTimeout(timer);
        reject(new DOMException("Aborted", "AbortError"));
        return;
      }

      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

async function withTimeout<T>(
  fn: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  parentSignal?: AbortSignal
): Promise<T> {
  const controller = new AbortController();

  const timeout = setTimeout(() => {
    controller.abort();
  }, timeoutMs);

  const onParentAbort = () => controller.abort();

  try {
    if (parentSignal) {
      if (parentSignal.aborted) {
        controller.abort();
      } else {
        parentSignal.addEventListener("abort", onParentAbort, { once: true });
      }
    }

    return await fn(controller.signal);
  } catch (err) {
    if (controller.signal.aborted && !parentSignal?.aborted) {
      throw new Error("Timeout");
    }
    throw err;
  } finally {
    clearTimeout(timeout);
    if (parentSignal) {
      parentSignal.removeEventListener("abort", onParentAbort);
    }
  }
}

function normalizeUnknownError(provider: AIProviderName, err: unknown): AIProviderError {
  if (err instanceof AIProviderError) return err;

  if (isAbortError(err)) {
    return new AIProviderError({
      provider,
      code: "ABORTED",
      message: "Request aborted",
      retryable: false,
      cause: err,
    });
  }

  if (err instanceof Error && err.message === "Timeout") {
    return new AIProviderError({
      provider,
      code: "TIMEOUT",
      message: "Provider request timed out",
      retryable: true,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    code: "UNKNOWN",
    message: err instanceof Error ? err.message : "Unknown provider error",
    retryable: false,
    cause: err,
  });
}
```

