## 3) Provider 구현 예시

실서비스에서는 각 SDK를 붙이면 됩니다.  
여기서는 **fetch 기반 예시**로 작성합니다.

### 3-1) OpenAI provider 예시

```ts
export class OpenAIProvider implements AIProvider {
  public readonly name = "openai" as const;
  public readonly model: string;
  private readonly apiKey: string;
  private readonly baseUrl: string;

  constructor(params: {
    apiKey: string;
    model: string;
    baseUrl?: string;
  }) {
    this.apiKey = params.apiKey;
    this.model = params.model;
    this.baseUrl = params.baseUrl ?? "https://api.openai.com/v1";
  }

  async generate(request: AIRequest): Promise<AIResponse> {
    try {
      const res = await fetch(`${this.baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${this.apiKey}`,
        },
        signal: request.signal,
        body: JSON.stringify({
          model: this.model,
          messages: request.messages,
          temperature: request.temperature,
          max_tokens: request.maxTokens,
        }),
      });

      if (!res.ok) {
        const text = await res.text();
        throw this.mapHttpError(res.status, text);
      }

      const data = await res.json();

      return {
        provider: this.name,
        model: this.model,
        content: data.choices?.[0]?.message?.content ?? "",
        usage: {
          inputTokens: data.usage?.prompt_tokens,
          outputTokens: data.usage?.completion_tokens,
          totalTokens: data.usage?.total_tokens,
        },
        raw: data,
      };
    } catch (err) {
      throw normalizeUnknownError(this.name, err);
    }
  }

  private mapHttpError(status: number, body: string): AIProviderError {
    if (status === 401 || status === 403) {
      return new AIProviderError({
        provider: this.name,
        code: "AUTH",
        message: `OpenAI auth error: ${body}`,
        status,
        retryable: false,
      });
    }

    if (status === 429) {
      return new AIProviderError({
        provider: this.name,
        code: "RATE_LIMIT",
        message: `OpenAI rate limit: ${body}`,
        status,
        retryable: true,
      });
    }

    if (status >= 400 && status < 500) {
      return new AIProviderError({
        provider: this.name,
        code: "INVALID_REQUEST",
        message: `OpenAI invalid request: ${body}`,
        status,
        retryable: false,
      });
    }

    return new AIProviderError({
      provider: this.name,
      code: "UPSTREAM",
      message: `OpenAI upstream error: ${body}`,
      status,
      retryable: true,
    });
  }
}
```

