### 3-2) Anthropic provider 예시

```ts
export class AnthropicProvider implements AIProvider {
  public readonly name = "anthropic" as const;
  public readonly model: string;
  private readonly apiKey: string;
  private readonly baseUrl: string;

  constructor(params: {
    apiKey: string;
    model: string;
    baseUrl?: string;
  }) {
    this.apiKey = params.apiKey;
    this.model = params.model;
    this.baseUrl = params.baseUrl ?? "https://api.anthropic.com/v1";
  }

  async generate(request: AIRequest): Promise<AIResponse> {
    try {
      const system = request.messages
        .filter((m) => m.role === "system")
        .map((m) => m.content)
        .join("\n");

      const messages = request.messages
        .filter((m) => m.role !== "system")
        .map((m) => ({
          role: m.role,
          content: m.content,
        }));

      const res = await fetch(`${this.baseUrl}/messages`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": this.apiKey,
          "anthropic-version": "2023-06-01",
        },
        signal: request.signal,
        body: JSON.stringify({
          model: this.model,
          system,
          messages,
          temperature: request.temperature,
          max_tokens: request.maxTokens ?? 1024,
        }),
      });

      if (!res.ok) {
        const text = await res.text();
        throw this.mapHttpError(res.status, text);
      }

      const data = await res.json();

      const content = Array.isArray(data.content)
        ? data.content
            .filter((c: any) => c.type === "text")
            .map((c: any) => c.text)
            .join("\n")
        : "";

      return {
        provider: this.name,
        model: this.model,
        content,
        usage: {
          inputTokens: data.usage?.input_tokens,
          outputTokens: data.usage?.output_tokens,
          totalTokens:
            (data.usage?.input_tokens ?? 0) + (data.usage?.output_tokens ?? 0),
        },
        raw: data,
      };
    } catch (err) {
      throw normalizeUnknownError(this.name, err);
    }
  }

  private mapHttpError(status: number, body: string): AIProviderError {
    if (status === 401 || status === 403) {
      return new AIProviderError({
        provider: this.name,
        code: "AUTH",
        message: `Anthropic auth error: ${body}`,
        status,
        retryable: false,
      });
    }

    if (status === 429) {
      return new AIProviderError({
        provider: this.name,
        code: "RATE_LIMIT",
        message: `Anthropic rate limit: ${body}`,
        status,
        retryable: true,
      });
    }

    if (status >= 400 && status < 500) {
      return new AIProviderError({
        provider: this.name,
        code: "INVALID_REQUEST",
        message: `Anthropic invalid request: ${body}`,
        status,
        retryable: false,
      });
    }

    return new AIProviderError({
      provider: this.name,
      code: "UPSTREAM",
      message: `Anthropic upstream error: ${body}`,
      status,
      retryable: true,
    });
  }
}
