# 3) 규칙 기반 평가기

이 단계는 빠르고 결정적입니다.  
LLM judge가 흔들려도 최소한의 품질 하한선을 보장합니다.

```ts
// judge/ruleBasedJudge.ts

import { CandidateResponse, JudgeInput, RuleBasedScore } from "./types";

function isBlank(text: string): boolean {
  return !text || text.trim().length === 0;
}

function hasCodeBlock(text: string): boolean {
  return /```[\s\S]*?```/.test(text);
}

function looksLikeJson(text: string): boolean {
  const trimmed = text.trim();
  return (
    (trimmed.startsWith("{") && trimmed.endsWith("}")) ||
    (trimmed.startsWith("[") && trimmed.endsWith("]"))
  );
}

function isValidJson(text: string): boolean {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
}

function containsDangerousContent(text: string): boolean {
  const patterns = [
    /how to make a bomb/i,
    /bypass security/i,
    /steal password/i,
    /malware/i,
    /ransomware/i,
  ];
  return patterns.some((p) => p.test(text));
}

function isOverlyShort(text: string): boolean {
  return text.trim().length < 40;
}

function mentionsCannotComply(text: string): boolean {
  return /i can('|’)t help with that|cannot assist with that|won't help with that|도와드릴 수 없습니다|제공할 수 없습니다/i.test(
    text
  );
}

export function scoreCandidateRuleBased(
  input: JudgeInput,
  candidate: CandidateResponse
): RuleBasedScore {
  let score = 50;
  const flags: string[] = [];
  const reasons: string[] = [];
  const content = candidate.content ?? "";

  if (isBlank(content)) {
    score -= 50;
    flags.push("blank");
    reasons.push("응답이 비어 있습니다.");
  }

  if (isOverlyShort(content)) {
    score -= 10;
    flags.push("too_short");
    reasons.push("응답이 지나치게 짧습니다.");
  }

  if (input.taskType === "code" && !hasCodeBlock(content)) {
    score -= 8;
    flags.push("missing_code_block");
    reasons.push("코드 요청인데 코드 블록이 없습니다.");
  }

  if (input.taskType === "json") {
    if (!looksLikeJson(content)) {
      score -= 15;
      flags.push("not_json_shape");
      reasons.push("JSON 요청인데 JSON 형태가 아닙니다.");
    } else if (!isValidJson(content)) {
      score -= 20;
      flags.push("invalid_json");
      reasons.push("JSON 파싱이 실패합니다.");
    }
  }

  if (containsDangerousContent(content)) {
    score -= 40;
    flags.push("dangerous_content");
    reasons.push("위험한 내용이 포함되어 있습니다.");
  }

  if (
    input.taskType === "safety_sensitive" &&
    containsDangerousContent(input.userPrompt) &&
    !mentionsCannotComply(content)
  ) {
    score -= 20;
    flags.push("unsafe_compliance");
    reasons.push("거절 또는 안전한 전환이 필요한 요청에 충분히 안전하게 대응하지 않았습니다.");
  }

  if (candidate.latencyMs && candidate.latencyMs > 15000) {
    score -= 3;
    flags.push("slow_response");
    reasons.push("응답 지연이 큽니다.");
  }

  score = Math.max(0, Math.min(100, score));

  return {
    provider: candidate.provider,
    score,
    flags,
    reasons,
  };
}

export function scoreAllRuleBased(input: JudgeInput): RuleBasedScore[] {
  return input.candidates.map((c) => scoreCandidateRuleBased(input, c));
}
```

