judge 모델은 반드시 **구조화된 JSON만 반환**하게 해야 합니다.  
또한 **position bias**를 줄이기 위해 후보 순서를 랜덤 셔플하는 것이 좋습니다.

```ts
// judge/prompt.ts

import { JudgeInput, CandidateResponse } from "./types";

export interface ShuffledCandidates {
  a: CandidateResponse;
  b: CandidateResponse;
  mapping: Record<"A" | "B", CandidateResponse["provider"]>;
}

export function shuffleCandidates(
  candidates: [CandidateResponse, CandidateResponse]
): ShuffledCandidates {
  const [c1, c2] = candidates;
  if (Math.random() < 0.5) {
    return {
      a: c1,
      b: c2,
      mapping: { A: c1.provider, B: c2.provider },
    };
  }
  return {
    a: c2,
    b: c1,
    mapping: { A: c2.provider, B: c1.provider },
  };
}

export function buildJudgePrompt(input: JudgeInput, shuffled: ShuffledCandidates): string {
  return `
