  provider: ProviderName;
  content: string;
  latencyMs: number;
  success: boolean;
  statusCode?: number;
  errorMessage?: string;
  metadata?: Record<string, unknown>;
}

interface ScoreContext {
  userPrompt: string;
  maxAllowedLatencyMs?: number;
  preferredProviders?: ProviderName[];
  bannedWords?: string[];
  minContentLength?: number;
}

interface ScoreBreakdownItem {
  criterion: string;
  rawScore: number;      // 0 ~ 1
  weightedScore: number; // rawScore * weight
  reason?: string;
}

interface ScoredResponse {
  response: ProviderResponse;
  totalScore: number;
  breakdown: ScoreBreakdownItem[];
}

interface WinnerResult {
  winner: ScoredResponse | null;
  ranked: ScoredResponse[];
}

interface ScoreCriterion {
  name: string;
  weight: number;
  evaluate(
    response: ProviderResponse,
    context: ScoreContext
  ): { rawScore: number; reason?: string };
}

class Scoreboard {
  constructor(private readonly criteria: ScoreCriterion[]) {
    const invalid = criteria.find(c => c.weight < 0);
    if (invalid) {
      throw new Error(`Criterion weight must be >= 0: ${invalid.name}`);
    }
  }

  score(
    response: ProviderResponse,
    context: ScoreContext
  ): { totalScore: number; breakdown: ScoreBreakdownItem[] } {
    const breakdown: ScoreBreakdownItem[] = [];
    let totalScore = 0;

    for (const criterion of this.criteria) {
      const result = criterion.evaluate(response, context);
      const rawScore = clamp(result.rawScore, 0, 1);
      const weightedScore = rawScore * criterion.weight;

      breakdown.push({
        criterion: criterion.name,
        rawScore,
        weightedScore,
        reason: result.reason,
      });

      totalScore += weightedScore;
    }

    return { totalScore, breakdown };
  }
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

// --------------------
// Criteria
// --------------------

class SuccessCriterion implements ScoreCriterion {
  name = 'success';
  constructor(public weight: number) {}

  evaluate(response: ProviderResponse) {
    if (response.success) {
      return { rawScore: 1, reason: 'Provider call succeeded' };
    }
    return {
      rawScore: 0,
      reason: response.errorMessage ?? 'Provider call failed',
    };
  }
}

class ContentLengthCriterion implements ScoreCriterion {
  name = 'content_length';
  constructor(public weight: number) {}

  evaluate(response: ProviderResponse, context: ScoreContext) {
    if (!response.success) {
      return { rawScore: 0, reason: 'No score because response failed' };
    }

    const minLength = context.minContentLength ?? 50;
    const length = response.content.trim().length;

    if (length === 0) {
      return { rawScore: 0, reason: 'Empty content' };
    }

    if (length >= minLength) {
      return { rawScore: 1, reason: `Content length ${length} >= ${minLength}` };
    }

    return {
      rawScore: length / minLength,
      reason: `Content length ${length} < ${minLength}`,
    };
  }
}

class LatencyCriterion implements ScoreCriterion {
  name = 'latency';
  constructor(public weight: number) {}

  evaluate(response: ProviderResponse, context: ScoreContext) {
    if (!response.success) {
      return { rawScore: 0, reason: 'No score because response failed' };
    }

    const maxLatency = context.maxAllowedLatencyMs ?? 5000;
    const latency = response.latencyMs;

    if (latency <= 0) {
      return { rawScore: 0, reason: 'Invalid latency' };
    }

    if (latency > maxLatency) {
      return {
        rawScore: 0,
        reason: `Latency ${latency}ms exceeded threshold ${maxLatency}ms`,
      };
    }

    // 빠를수록 높은 점수
    const rawScore = 1 - latency / maxLatency;
    return {
      rawScore: Math.max(0.1, rawScore),
      reason: `Latency ${latency}ms within threshold ${maxLatency}ms`,
    };
  }
}

class BannedWordsCriterion implements ScoreCriterion {
  name = 'banned_words';
  constructor(public weight: number) {}

  evaluate(response: ProviderResponse, context: ScoreContext) {
    if (!response.success) {
      return { rawScore: 0, reason: 'No score because response failed' };
    }

    const bannedWords = context.bannedWords ?? [];
    if (bannedWords.length === 0) {
      return { rawScore: 1, reason: 'No banned words configured' };
    }

    const lower = response.content.toLowerCase();
    const found = bannedWords.filter(word => lower.includes(word.toLowerCase()));

    if (found.length > 0) {
      return {
        rawScore: 0,
        reason: `Contains banned words: ${found.join(', ')}`,
      };
    }

    return { rawScore: 1, reason: 'No banned words found' };
  }
}

class PreferredProviderCriterion implements ScoreCriterion {
  name = 'preferred_provider';
  constructor(public weight: number) {}

  evaluate(response: ProviderResponse, context: ScoreContext) {
    const preferred = context.preferredProviders ?? [];

    if (preferred.length === 0) {
      return { rawScore: 0.5, reason: 'No preferred providers configured' };
    }

