export type StepType = "fetchUserData" | "summarizeData";

export interface GoalInput {
  requestId: string;
  userId: string;
  goal: string;
}

export interface PlanStep {
  id: string;
  type: StepType;
  input: Record<string, unknown>;
  timeoutMs?: number;
  retryCount?: number;
}

export interface Plan {
  planId: string;
  goal: string;
  steps: PlanStep[];
  createdAt: string;
}

export interface StepExecutionResult {
  stepId: string;
  type: StepType;
  success: boolean;
  output?: Record<string, unknown>;
  error?: string;
  startedAt: string;
  finishedAt: string;
  attempts: number;
}

export interface ExecutionResult {
  planId: string;
  success: boolean;
  stepResults: StepExecutionResult[];
  startedAt: string;
  finishedAt: string;
}

export interface JudgeResult {
  success: boolean;
  score: number;
  reasons: string[];
  finalOutput?: Record<string, unknown>;
}

export interface OrchestrationResult {
  input: GoalInput;
  plan: Plan;
  execution: ExecutionResult;
  judgment: JudgeResult;
}

export interface Planner {
  createPlan(input: GoalInput): Promise<Plan>;
}

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

export interface Judge {
  evaluate(
    input: GoalInput,
    plan: Plan,
    execution: ExecutionResult
  ): Promise<JudgeResult>;
}
