```ts
import {
  Executor,
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types";
import { nowIso, retry, sleep, withTimeout } from "./utils";

type ExecutionContext = {
  stepOutputs: Record<string, Record<string, unknown>>;
  latestUserData?: Record<string, unknown>;
};

export class SimpleExecutor implements Executor {
  async execute(plan: Plan): Promise<ExecutionResult> {
    const startedAt = nowIso();
    const stepResults: StepExecutionResult[] = [];
    const context: ExecutionContext = {
      stepOutputs: {}
    };

    for (const step of plan.steps) {
      const result = await this.executeStep(step, context);
      stepResults.push(result);

      if (!result.success) {
        return {
          planId: plan.planId,
          success: false,
          stepResults,
          startedAt,
          finishedAt: nowIso()
        };
      }

      if (result.output) {
        context.stepOutputs[step.id] = result.output;

        if (step.type === "fetchUserData") {
          context.latestUserData = result.output;
        }
      }
    }

    return {
      planId: plan.planId,
      success: true,
      stepResults,
      startedAt,
      finishedAt: nowIso()
    };
  }

  private async executeStep(
    step: PlanStep,
    context: ExecutionContext
  ): Promise<StepExecutionResult> {
    const startedAt = nowIso();
    const timeoutMs = step.timeoutMs ?? 3_000;
    const retryCount = step.retryCount ?? 0;

    try {
      const { result, attempts } = await retry(
        async () =>
          withTimeout(
            () => this.runStep(step, context),
            timeoutMs,
            `step:${step.type}:${step.id}`
          ),
        retryCount,
        200,
        () => true
      );

      return {
        stepId: step.id,
        type: step.type,
        success: true,
        output: result,
        startedAt,
        finishedAt: nowIso(),
        attempts
      };
    } catch (error) {
      const message =
        error instanceof Error
          ? `${error.message}${
              "cause" in error && error.cause
                ? ` | cause: ${String(error.cause)}`
                : ""
            }`
          : String(error);

      const attempts =
        typeof error === "object" &&
        error !== null &&
        "attempts" in error &&
        typeof (error as { attempts: unknown }).attempts === "number"
          ? (error as { attempts: number }).attempts
          : retryCount + 1;

      return {
        stepId: step.id,
        type: step.type,
        success: false,
        error: message,
        startedAt,
        finishedAt: nowIso(),
        attempts
      };
    }
  }

  private async runStep(
    step: PlanStep,
    context: ExecutionContext
  ): Promise<Record<string, unknown>> {
    switch (step.type) {
      case "fetchUserData":
        return this.fetchUserData(step.input);

      case "summarizeData":
        return this.summarizeData(context);

      default: {
        const exhaustiveCheck: never = step.type;
        throw new Error(`Unsupported step type: ${exhaustiveCheck}`);
      }
    }
  }

  private async fetchUserData(
    input: Record<string, unknown>
  ): Promise<Record<string, unknown>> {
    await sleep(300);

    const userId = String(input.userId ?? "unknown");

    return {
      userId,
      name: "Jane Doe",
      age: 29,
      country: "KR",
      lastLoginAt: "2026-03-15T10:00:00.000Z",
      purchases: 12
    };
  }

  private async summarizeData(
    context: ExecutionContext
  ): Promise<Record<string, unknown>> {
    await sleep(200);

    if (!context.latestUserData) {
      throw new Error("No user data available for summarization");
    }

    const name = String(context.latestUserData.name ?? "Unknown");
    const country = String(context.latestUserData.country ?? "Unknown");
    const purchases = Number(context.latestUserData.purchases ?? 0);

    return {
      summary: `${name} is a user from ${country} with ${purchases} purchases.`,
      summaryLength: 1
    };
  }
}
