    const timeoutMs = step.timeoutMs ?? 3_000;
    const retryCount = step.retryCount ?? 0;

    try {
      const { result, attempts } = await retry(
        async () =>
          withTimeout(
            () => this.runStep(step, context),
            timeoutMs,
            `step:${step.type}:${step.id}`
          ),
        retryCount,
        200,
        () => true
      );

      return {
        stepId: step.id,
        type: step.type,
        success: true,
        output: result,
        startedAt,
        finishedAt: nowIso(),
        attempts
      };
    } catch (error) {
      const message =
        error instanceof Error
          ? `${error.message}${
              "cause" in error && error.cause
                ? ` | cause: ${String(error.cause)}`
                : ""
            }`
          : String(error);

      const attempts =
        typeof error === "object" &&
        error !== null &&
        "attempts" in error &&
        typeof (error as { attempts: unknown }).attempts === "number"
          ? (error as { attempts: number }).attempts
          : retryCount + 1;

      return {
        stepId: step.id,
        type: step.type,
        success: false,
        error: message,
        startedAt,
        finishedAt: nowIso(),
        attempts
      };
    }
