# 8) Planner 구현: `src/planner.ts`

여기서는 매우 단순한 rule-based planner를 사용합니다.

```ts
import { GoalInput, Plan, Planner, PlanStep } from "./types";
import { nowIso } from "./utils";
import { randomUUID } from "crypto";

export class SimplePlanner implements Planner {
  async createPlan(input: GoalInput): Promise<Plan> {
    const steps: PlanStep[] = [];

    // 간단한 규칙 기반 계획
    if (input.goal.toLowerCase().includes("summary")) {
      steps.push({
        id: randomUUID(),
        type: "fetchUserData",
        input: { userId: input.userId },
        timeoutMs: 2_000,
        retryCount: 1
      });

      steps.push({
        id: randomUUID(),
        type: "summarizeData",
        input: {},
        timeoutMs: 2_000,
        retryCount: 0
      });
    } else {
      // 기본 플랜
      steps.push({
        id: randomUUID(),
        type: "fetchUserData",
        input: { userId: input.userId },
        timeoutMs: 2_000,
        retryCount: 1
      });
    }

    return {
      planId: randomUUID(),
      goal: input.goal,
      steps,
      createdAt: nowIso()
    };
  }
}
```

